def taglio(x, L, carichi):
    x = np.asarray(x, dtype=float)
    RA, _ = reazioni(L, carichi)
    T = np.full_like(x, RA)
    for c in carichi:
        if c[0] == "F":
            _, F, a = c
            T -= F * (x >= a)
        else:
            _, q, a, b = c
            T -= q * np.clip(x - a, 0, b - a)
    return T
